function lesson_release_display(?string $utc): string {if(!$utc)return '';try{$dt=new DateTimeImmutable($utc);$tz=new DateTimeZone((string)(app_config()['timezone']??'UTC'));return $dt->setTimezone($tz)->format('d/m/Y · H:i');}catch(Throwable){return (string)$utc;}}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!verify_csrf('lessons-admin',$_POST['_csrf']??null)){http_response_code(403);exit('Invalid request');}$action=(string)($_POST['action']??'');
 try{
  if($action==='add_lesson')course_add_lesson_for_course($db,$courseId,(string)($_POST['title']??''),(string)($_POST['lesson_key']??''));
  elseif($action==='update_lesson')admin_course_update_lesson($db,$courseId,(int)($_POST['lesson_id']??0),(string)($_POST['title']??''));
  elseif($action==='move_lesson')admin_course_move_lesson($db,$courseId,(int)($_POST['lesson_id']??0),(int)($_POST['direction']??0));
  elseif($action==='set_release'){if(!$cohort)throw new RuntimeException('Escolha a turma.');course_set_lesson_release_for_course($db,$courseId,$cohortId,(int)($_POST['lesson_id']??0),(string)($_POST['mode']??'block'),(string)($_POST['scheduled_at']??''));}
  elseif($action==='save_meeting'){if(!$cohort)throw new RuntimeException('Escolha uma turma.');course_agenda_save_lesson_configuration($db,$courseId,$cohortId,(int)($_POST['lesson_id']??0),$_POST);}
  elseif($action==='save_agenda_settings'){if(!$cohort)throw new RuntimeException('Escolha uma turma.');course_agenda_save_settings($db,$courseId,$cohortId,$_POST);}
  elseif($action==='set_tool_release'){student_tool_course_set_release_lesson($db,$courseId,(string)($_POST['tool_key']??''),(int)($_POST['release_lesson_id']??0)?:null);}
  else throw new RuntimeException('Ação inválida.');$_SESSION['admin_lessons_notice']='Alteração salva.';
 }catch(Throwable $e){$_SESSION['admin_lessons_notice']='Não foi possível concluir: '.$e->getMessage();}
 $target=$cohort?admin_cohort_url($activityId,$courseId,$cohortId,'lessons'):admin_course_url($activityId,$courseId,'lessons');header('Location: '.$target,true,303);exit;
}
$lessons=course_lessons_for_course($db,$courseId);$impact=admin_course_lesson_material_impact($db,$courseId);$materials=course_material_pages($db,$courseId);$notice=(string)($_SESSION['admin_lessons_notice']??'');unset($_SESSION['admin_lessons_notice']);$tone=str_starts_with($notice,'Não foi possível')?'error':'success';
admin_shell_start('lessons',$cohort?'Aulas e acesso':'Aulas',$state,['/assets/admin-teaching.css','/assets/admin-operations.css']);?>
